// Plates generated by shaders: a leaf under a loupe, a geological survey, a contour map, plant cells
// and the moon. Baked once into canvases, then treated like the painted plates.

const LEAF_FS = `
uniform vec2 res;
void main(){
  vec2 px = uv * res, p = (px - res * .5) / res.y;
  float a = -.62; mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
  vec2 q = R * p; q.y += .06 * q.x * q.x;
  float u = q.x, v = q.y, av = abs(v);
  // secondary veins sweep forward from the midrib
  float ph = (u - pow(av, .85) * 1.05 - .3 * av * av + .06 * fbm(q * 2.5 + 3.)) * 7.;
  float fv = abs(fract(ph) - .5);
  float sec = smoothstep(.055, .0, fv * (1. - .35 * av));
  vec3 ve = voronoiEdge(q * 34.);
  float ter = smoothstep(.06, .0, ve.x);
  vec3 ve2 = voronoiEdge(q * 110. + 3.);
  float qua = smoothstep(.07, .0, ve2.x);
  float puck = sin(fract(ph) * 3.1416);
  float n = fbm(q * 5.), n2 = fbm(q * 40.);
  vec3 deep = vec3(.11, .26, .07), mid = vec3(.24, .45, .13), light = vec3(.52, .68, .26);
  vec3 c = mix(deep, mid, .55 + .35 * n + .25 * puck);
  c = mix(c, light, .18 * smoothstep(.2, .9, puck) + .1 * n2);
  c = mix(c, c * .78, .2 * smoothstep(.0, .3, -v));
  c = mix(c, light * 1.05, ter * .28);
  c = mix(c, light * .9, qua * .1);
  float sec2 = smoothstep(.09, .0, abs(fract(ph + .03) - .5));
  c = mix(c, deep * .7, sec2 * .35 * (1. - sec));
  c = mix(c, vec3(.72, .8, .42), sec * .85);
  float mr = smoothstep(.022, .006, av);
  c = mix(c, vec3(.8, .84, .5), mr);
  c = mix(c, deep * .6, smoothstep(.03, .02, av) * smoothstep(.01, .022, av) * .7 * step(0., v));
  c += vec3(.9, 1., .8) * .12 * pow(max(0., fbm(q * 2.5 + 7.)), 2.);
  float edge = .95 + .03 * sin(u * 60.) - .08 * u;
  float inside = smoothstep(edge + .004, edge - .004, av);
  vec3 bg = mix(vec3(.08, .14, .06), vec3(.3, .38, .2), uv.y);
  c = mix(bg, c, inside);
  o = vec4(srgb(lin(c) * 1.1), 1);
}`;

const GEOLOGY_FS = `
uniform vec2 res;
vec3 pal(float i){
  i = mod(i, 9.);
  if (i < 1.) return vec3(.96, .72, .76); if (i < 2.) return vec3(.88, .45, .6); if (i < 3.) return vec3(.98, .94, .55);
  if (i < 4.) return vec3(.8, .74, .9); if (i < 5.) return vec3(.7, .84, .93); if (i < 6.) return vec3(.94, .8, .52);
  if (i < 7.) return vec3(.62, .84, .5); if (i < 8.) return vec3(.98, .86, .78); return vec3(.7, .64, .86);
}
void main(){
  vec2 px = uv * res, p = px / 1500.;
  vec2 w = vec2(fbm4(p * 1.1 + 1.7), fbm4(p * 1.1 + 9.2));
  vec2 w2 = vec2(fbm4(p * 1.6 + w * 1.5 + 4.), fbm4(p * 1.6 + w * 1.5 + 12.));
  float f = p.x * 1.3 + p.y * .25 + .9 * fbm4(p * .8 + w2 * 1.2) + .4 * w2.x;
  float bands = f * 3.2;
  float id = floor(bands), fr = fract(bands);
  vec3 c = pal(id + floor(hash12(vec2(id, 3.)) * 2.));
  float d = min(fr, 1. - fr) / fwidth(bands);
  c = mix(c * .5, c, smoothstep(.4, 1.3, d));
  float h = hash12(vec2(id, 7.));
  vec2 g = px / 14.; vec2 cell = fract(g) - .5;
  if (h < .3) c *= 1. - .16 * smoothstep(.16, .08, length(cell + (hash22(floor(g)) - .5) * .4));
  else if (h < .55) c *= 1. - .18 * smoothstep(.1, .0, abs(fract((px.x - px.y) / 11.) - .5) - .38);
  else if (h < .65) { vec2 g2 = px / 26.; c *= 1. - .3 * smoothstep(.12, .05, abs(length(fract(g2) - .5) - .25)); }
  float riv = fbm4(p * 1.4 + 30.);
  c = mix(c, vec3(.2, .38, .7), smoothstep(.012, .004, abs(riv)) * .9);
  float fault = fbm4(p * .8 + 50.) + .2 * p.x;
  float dash = step(.5, fract(dot(px, vec2(.7, .7)) / 40.));
  c = mix(c, vec3(.6, .12, .12), smoothstep(.006, .002, abs(fault - .25)) * dash);
  vec2 gr = abs(fract(px / 460.) - .5);
  c = mix(c, c * .6, smoothstep(.4982, .4994, max(gr.x, gr.y)));
  c *= .94 + .06 * vnoise(px / 2.);
  c *= .97 + .05 * fbm(px / 200.);
  o = vec4(c, 1);
}`;

const TOPO_FS = `
uniform vec2 res;
float H(vec2 px){ vec2 p = px / 1500.; vec2 w = vec2(fbm4(p + 3.), fbm4(p + 8.)); return fbm4(p * 1.2 + w * .6) * 1.2 + .12 * abs(fbm4(p * 3. + 2.)); }
void main(){
  vec2 px = uv * res, p = px / 1100.;
  float h = H(px);
  float lv = h * 24.;
  float fw = fwidth(lv);
  float line = 1. - smoothstep(.0, 1.3, min(fract(lv), 1. - fract(lv)) / fw);
  float idx = 1. - smoothstep(.0, 2.2, min(fract(lv / 5.), 1. - fract(lv / 5.)) * 5. / fw);
  vec3 tint = mix(vec3(.84, .9, .74), vec3(.96, .9, .76), smoothstep(-.4, .3, h));
  tint = mix(tint, vec3(.97, .95, .9), smoothstep(.35, .7, h));
  float hx = H(px + vec2(3, 0)) - H(px - vec2(3, 0)), hy = H(px + vec2(0, 3)) - H(px - vec2(0, 3));
  float shade = clamp(.5 - (hx - hy) * 40., 0., 1.);
  vec3 c = tint * (.9 + .16 * shade);
  c = mix(c, vec3(.55, .33, .18), line * .75);
  c = mix(c, vec3(.42, .22, .1), idx * .9);
    c = mix(c, vec3(.25, .45, .75), smoothstep(.006, .002, abs(fbm4(p * 1.1 + 70.))) * .9);
  vec2 gr = abs(fract(px / 520.) - .5);
  c = mix(c, vec3(.3, .4, .6), .5 * smoothstep(.4984, .4995, max(gr.x, gr.y)));
  c *= .95 + .05 * vnoise(px / 2.);
  o = vec4(c, 1);
}`;

const CELLS_FS = `
uniform vec2 res;
void main(){
  vec2 px = uv * res, p = (px - res * .5) / res.y;
  vec2 q = p * 6.5 + .3 * vec2(fbm(p * 3.), fbm(p * 3. + 5.));
  vec3 e = voronoiEdge(q);
  float wall = smoothstep(.07, .03, e.x);
  float cell = smoothstep(.04, .2, e.x);
  vec2 id = e.yz;
  vec4 v = voronoi(q * 4.2 + id * 3.1);
  float chl = smoothstep(.36, .26, v.x) * smoothstep(.08, .3, e.x);
  vec3 bg = vec3(.86, .93, .72);
  vec3 c = mix(bg, vec3(.6, .78, .4), cell * .5);
  vec3 chc = mix(vec3(.1, .38, .1), vec3(.25, .55, .16), hash12(v.zw));
  c = mix(c, chc, chl * smoothstep(.35, .05, e.x) * .95 + chl * .25);
  c += vec3(.25, .3, .1) * chl * smoothstep(.2, .0, v.x) * .6;
  c = mix(c, vec3(.92, .98, .78), wall);
  c = mix(c, vec3(.35, .55, .2), smoothstep(.02, .0, abs(e.x - .07)) * .6);
  float centre = smoothstep(.22, .0, length(p));
  c = mix(c, vec3(.95, 1., .85), centre * .55);
  c *= 1. - .25 * smoothstep(.3, .8, length(p));
  o = vec4(c, 1);
}`;

const MOON_FS = `
uniform vec2 res;
float crater(vec2 p, float sc, float seed, inout float rim){
  vec4 v = voronoi(p * sc + seed);
  float r = .18 + .3 * hash12(v.zw + seed);
  if (hash12(v.zw * 1.7 + seed) < .45) return 0.;
  float d = v.x / r;
  rim += smoothstep(.75, 1., d) * smoothstep(1.3, 1., d);
  return smoothstep(1., .0, d);
}
float heightAt(vec2 s, inout float rim){
  return crater(s, 3., 1., rim) + crater(s, 7., 2., rim) * .7 + crater(s, 16., 3., rim) * .45 + crater(s, 34., 4., rim) * .3;
}
void main(){
  vec2 px = uv * res, p = (px - res * .5) / (res.y * .42);
  float r = length(p);
  if (r > 1.) { o = vec4(vec3(0.), 1); return; }
  vec3 n = vec3(p, sqrt(1. - r * r));
  vec2 s = vec2(atan(n.x, n.z), asin(n.y)) * 1.6;
  float mare = smoothstep(.0, .35, fbm(s * 1.2 + 4.) + .1);
  float alb = mix(.8, .48, mare) + .08 * fbm(s * 6.);
  float rim = 0., dummy = 0.;
  float h = heightAt(s, rim);
  float hr = heightAt(s + vec2(.004, 0), dummy);
  float slope = (hr - h) / .004;
  float lit = .82 + .5 * clamp(slope * .025, -.6, .6);
  float c = alb * lit + rim * .12;
  vec2 rc = s - vec2(.5, -.9);
  c += .12 * smoothstep(.6, .95, sin(atan(rc.y, rc.x) * 23.) * .5 + .5) * exp(-length(rc) * 2.5) * (1. - mare);
  c *= .55 + .45 * pow(n.z, .35);
  c *= .9 + .1 * vnoise(px / 1.5);
  c *= smoothstep(1., .995, r);
  o = vec4(vec3(c) * vec3(1., .99, .97), 1);
}`;

function shaderPlates() {
  PLATES.leaf = bake(LEAF_FS, 2048, 2048);
  PLATES.geology = bake(GEOLOGY_FS, 2600, 2048);
  PLATES.topo = bake(TOPO_FS, 2400, 2048);
  PLATES.moon = bake(MOON_FS, 2048, 2048);
}

// the cells, alive: chloroplasts stream round each cell while the lens pushes in
const CELLS_LIVE_FS = CELLS_FS
  .replace("uniform vec2 res;", "uniform vec2 res; uniform float time, zoom;")
  .replace("vec2 px = uv * res, p = (px - res * .5) / res.y;", "vec2 px = uv * res, p = (uv - .5) * zoom;")
  .replace("vec4 v = voronoi(q * 4.2 + id * 3.1);", "vec4 v = voronoi(q * 4.2 + id * 3.1 + time * .5 * vec2(sin(id.x * 7.1), cos(id.y * 5.3)));");
